// A focused replica of the CPython `argparse` behaviour exercised by
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//     args = parser.parse_args()
//
// Ported from CPython 3.12's Lib/argparse.py (the reference binary embeds
// libpython3.12; its heading is `options:`, and its `-ha` / `-h=x` behaviour
// matches the `sep`-aware variant of `consume_optional`).
//
// Nothing here touches process/stdout/stderr: `parseArgs` returns a structured
// result and the entry point decides what to write and which code to exit with.
//
//   { ok: true,  args: { a: '...' } }
//   { ok: false, exitCode: 0, stdout: <help text>, stderr: '' }
//   { ok: false, exitCode: 2, stdout: '', stderr: <usage + error line> }

export const SUPPRESS = '==SUPPRESS==';
export const OPTIONAL = '?';

// os.path.basename, posix flavour.
export function basename(path) {
  const i = path.lastIndexOf('/');
  return i === -1 ? path : path.slice(i + 1);
}

const ASCII_DIGITS = '0123456789';
const PY_SPACES = ' \t\n\r\f\v';

function isSpace(ch) {
  return PY_SPACES.includes(ch);
}

// Unicode `Nd` block starts (each covers 10 consecutive code points), so that
// Python's `\d` — which is Unicode-aware for str patterns — is reproduced.
// Confirmed against the binary: `--a -<arabic-indic one><two>` is accepted as
// a value, i.e. the negative-number matcher fired on non-ASCII digits.
const ND_BLOCK_STARTS = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
  0x11d50, 0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8,
  0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

function isDigitChar(ch) {
  if (ASCII_DIGITS.includes(ch)) return true;
  const cp = ch.codePointAt(0);
  for (const start of ND_BLOCK_STARTS) {
    if (cp >= start && cp <= start + 9) return true;
  }
  return false;
}

// argparse: `_negative_number_matcher = re.compile(r'^-\d+$|^-\d*\.\d+$')`,
// applied with re.match. Python's `$` also matches just before a single
// trailing newline, which is why `--a $'-1\n'` is accepted as a value.
export function isNegativeNumber(s) {
  const chars = Array.from(s);
  let n = chars.length;
  if (n > 0 && chars[n - 1] === '\n') n -= 1; // trailing-newline `$`
  if (n < 2 || chars[0] !== '-') return false;
  // ^-\d+$
  let allDigits = true;
  for (let i = 1; i < n; i += 1) {
    if (!isDigitChar(chars[i])) { allDigits = false; break; }
  }
  if (allDigits) return true;
  // ^-\d*\.\d+$
  let i = 1;
  while (i < n && isDigitChar(chars[i])) i += 1;
  if (i >= n || chars[i] !== '.') return false;
  i += 1;
  if (i >= n) return false;
  for (; i < n; i += 1) {
    if (!isDigitChar(chars[i])) return false;
  }
  return true;
}

// Python's repr() of a str, for the `ignored explicit argument %r` message.
export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + (cp < 0x10 ? '0' : '') + cp.toString(16);
    } else out += ch;
  }
  return out + quote;
}

function padRight(s, width) {
  return s.length >= width ? s : s + ' '.repeat(width - s.length);
}

// `re.compile(r'\n\n\n+').sub('\n\n', text)`
function collapseLongBreaks(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '\n') {
      let j = i;
      while (j < text.length && text[j] === '\n') j += 1;
      out += j - i >= 3 ? '\n\n' : text.slice(i, j);
      i = j;
    } else {
      out += text[i];
      i += 1;
    }
  }
  return out;
}

// str.strip('\n')
function stripNewlines(text) {
  let a = 0;
  let b = text.length;
  while (a < b && text[a] === '\n') a += 1;
  while (b > a && text[b - 1] === '\n') b -= 1;
  return text.slice(a, b);
}

// `self._whitespace_matcher.sub(' ', text).strip()` — `\s+` collapsed.
function normalizeWhitespace(text) {
  let out = '';
  let pendingSpace = false;
  for (const ch of text) {
    if (isSpace(ch)) { pendingSpace = true; continue; }
    if (pendingSpace && out) out += ' ';
    pendingSpace = false;
    out += ch;
  }
  return out;
}

// textwrap.wrap(text, width) for the simple (already whitespace-normalised)
// help strings this program uses.
function wrapText(text, width) {
  const words = text.split(' ').filter((w) => w !== '');
  const lines = [];
  let line = '';
  for (let word of words) {
    while (word.length > width) {
      if (line) { lines.push(line); line = ''; }
      lines.push(word.slice(0, width));
      word = word.slice(width);
    }
    if (!line) line = word;
    else if (line.length + 1 + word.length <= width) line += ' ' + word;
    else { lines.push(line); line = word; }
  }
  if (line) lines.push(line);
  return lines;
}

// argparse's usage-splitting regex:
//   \(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+
function usageParts(text) {
  const parts = [];
  let i = 0;
  while (i < text.length) {
    if (isSpace(text[i])) { i += 1; continue; }
    let end = null;
    if (text[i] === '(') end = bracketMatch(text, i, ')');
    else if (text[i] === '[') end = bracketMatch(text, i, ']');
    if (end === null) {
      let j = i;
      while (j < text.length && !isSpace(text[j])) j += 1;
      parts.push(text.slice(i, j));
      i = j;
    } else {
      parts.push(text.slice(i, end));
      i = end;
    }
  }
  return parts;
}

// `\[.*?\]+(?=\s|$)`: shortest non-newline run, then a greedy (backtracking)
// run of closers, then whitespace or end of string. Returns the end index.
function bracketMatch(text, start, close) {
  const n = text.length;
  for (let mid = start + 1; mid < n; mid += 1) {
    if (text[mid] === '\n') return null; // `.` does not match a newline
    if (text[mid] !== close) continue;
    let last = mid;
    while (last + 1 < n && text[last + 1] === close) last += 1;
    for (let end = last; end >= mid; end -= 1) {
      if (end + 1 >= n || isSpace(text[end + 1])) return end + 1;
    }
  }
  return null;
}

class Section {
  constructor(formatter, parent, heading = null) {
    this.formatter = formatter;
    this.parent = parent;
    this.heading = heading;
    this.items = [];
  }

  formatHelp() {
    const f = this.formatter;
    if (this.parent !== null) f._indent();
    const itemHelp = f._joinParts(this.items.map(([func, args]) => func.apply(f, args)));
    if (this.parent !== null) f._dedent();
    if (!itemHelp) return '';
    let heading = '';
    if (this.heading !== SUPPRESS && this.heading !== null) {
      heading = ' '.repeat(f._currentIndent) + this.heading + ':\n';
    }
    return f._joinParts(['\n', heading, itemHelp, '\n']);
  }
}

export class HelpFormatter {
  constructor(prog, indentIncrement = 2, maxHelpPosition = 24, width = 78) {
    this._prog = prog;
    this._indentIncrement = indentIncrement;
    this._maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(width - 20, indentIncrement * 2),
    );
    this._width = width;
    this._currentIndent = 0;
    this._level = 0;
    this._actionMaxLength = 0;
    this._rootSection = new Section(this, null);
    this._currentSection = this._rootSection;
  }

  _indent() {
    this._currentIndent += this._indentIncrement;
    this._level += 1;
  }

  _dedent() {
    this._currentIndent -= this._indentIncrement;
    this._level -= 1;
  }

  _addItem(func, args) {
    this._currentSection.items.push([func, args]);
  }

  startSection(heading) {
    this._indent();
    const section = new Section(this, this._currentSection, heading);
    this._addItem(section.formatHelp, []);
    this._currentSection = section;
  }

  endSection() {
    this._currentSection = this._currentSection.parent;
    this._dedent();
  }

  addText(text) {
    if (text !== SUPPRESS && text !== null && text !== undefined) {
      this._addItem(this._formatText, [text]);
    }
  }

  addUsage(usage, actions) {
    if (usage !== SUPPRESS) this._addItem(this._formatUsage, [usage, actions]);
  }

  addArgument(action) {
    if (action.help !== SUPPRESS) {
      const invocationLength = this._formatActionInvocation(action).length;
      const actionLength = invocationLength + this._currentIndent;
      this._actionMaxLength = Math.max(this._actionMaxLength, actionLength);
      this._addItem(this._formatAction, [action]);
    }
  }

  addArguments(actions) {
    for (const action of actions) this.addArgument(action);
  }

  formatHelp() {
    let help = this._rootSection.formatHelp();
    if (help) {
      help = collapseLongBreaks(help);
      help = stripNewlines(help) + '\n';
    }
    return help;
  }

  _joinParts(partStrings) {
    return partStrings.filter((p) => p && p !== SUPPRESS).join('');
  }

  _formatUsage(usage, actions) {
    const prefix = 'usage: ';
    if (usage !== null && usage !== undefined) {
      usage = usage.replaceAll('%(prog)s', this._prog);
    } else if (actions.length === 0) {
      usage = this._prog;
    } else {
      const prog = this._prog;
      const optionals = [];
      const positionals = [];
      for (const action of actions) {
        if (action.optionStrings.length) optionals.push(action);
        else positionals.push(action);
      }
      const actionUsage = this._formatActionsUsage(optionals.concat(positionals));
      usage = [prog, actionUsage].filter((s) => s).join(' ');

      const textWidth = this._width - this._currentIndent;
      if (prefix.length + usage.length > textWidth) {
        const optParts = usageParts(this._formatActionsUsage(optionals));
        const posParts = usageParts(this._formatActionsUsage(positionals));

        const getLines = (parts, indent, linePrefix = null) => {
          const lines = [];
          let line = [];
          let lineLen = (linePrefix !== null ? linePrefix.length : indent.length) - 1;
          for (const part of parts) {
            if (lineLen + 1 + part.length > textWidth && line.length) {
              lines.push(indent + line.join(' '));
              line = [];
              lineLen = indent.length - 1;
            }
            line.push(part);
            lineLen += 1 + part.length;
          }
          if (line.length) lines.push(indent + line.join(' '));
          if (linePrefix !== null && lines.length) lines[0] = lines[0].slice(indent.length);
          return lines;
        };

        let lines;
        if (prefix.length + prog.length <= 0.75 * textWidth) {
          const indent = ' '.repeat(prefix.length + prog.length + 1);
          if (optParts.length) {
            lines = getLines([prog].concat(optParts), indent, prefix);
            lines = lines.concat(getLines(posParts, indent));
          } else if (posParts.length) {
            lines = getLines([prog].concat(posParts), indent, prefix);
          } else {
            lines = [prog];
          }
        } else {
          const indent = ' '.repeat(prefix.length);
          lines = getLines(optParts.concat(posParts), indent);
          if (lines.length > 1) {
            lines = getLines(optParts, indent).concat(getLines(posParts, indent));
          }
          lines = [prog].concat(lines);
        }
        usage = lines.join('\n');
      }
    }
    return `${prefix}${usage}\n\n`;
  }

  // Simplified `_format_actions_usage`: this parser has no mutually exclusive
  // groups, so the group-bracket insertion and its regex cleanup collapse to a
  // plain join of the per-action parts.
  _formatActionsUsage(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      if (!action.optionStrings.length) {
        parts.push(this._formatArgs(action, action.dest));
        continue;
      }
      const optionString = action.optionStrings[0];
      let part;
      if (action.nargs === 0) {
        part = optionString;
      } else {
        const argsString = this._formatArgs(action, this._getDefaultMetavarForOptional(action));
        part = `${optionString} ${argsString}`;
      }
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts.join(' ');
  }

  _formatText(text) {
    const textWidth = Math.max(this._width - this._currentIndent, 11);
    const indent = ' '.repeat(this._currentIndent);
    return this._fillText(text, textWidth, indent) + '\n\n';
  }

  _fillText(text, width, indent) {
    return wrapText(normalizeWhitespace(text), width)
      .map((line) => indent + line)
      .join('\n');
  }

  _formatAction(action) {
    const helpPosition = Math.min(this._actionMaxLength + 2, this._maxHelpPosition);
    const helpWidth = Math.max(this._width - helpPosition, 11);
    const actionWidth = helpPosition - this._currentIndent - 2;
    let actionHeader = this._formatActionInvocation(action);
    let indentFirst = 0;

    if (!action.help) {
      actionHeader = ' '.repeat(this._currentIndent) + actionHeader + '\n';
    } else if (actionHeader.length <= actionWidth) {
      actionHeader = ' '.repeat(this._currentIndent) + padRight(actionHeader, actionWidth) + '  ';
      indentFirst = 0;
    } else {
      actionHeader = ' '.repeat(this._currentIndent) + actionHeader + '\n';
      indentFirst = helpPosition;
    }

    const parts = [actionHeader];
    if (action.help && action.help.trim()) {
      const helpText = this._expandHelp(action);
      if (helpText) {
        const helpLines = this._splitLines(helpText, helpWidth);
        parts.push(' '.repeat(indentFirst) + helpLines[0] + '\n');
        for (const line of helpLines.slice(1)) {
          parts.push(' '.repeat(helpPosition) + line + '\n');
        }
      }
    } else if (!actionHeader.endsWith('\n')) {
      parts.push('\n');
    }
    return this._joinParts(parts);
  }

  // CPython 3.12 spelling: `-s ARGS, --long ARGS` (3.13 changed this).
  _formatActionInvocation(action) {
    if (!action.optionStrings.length) {
      const [metavar] = this._metavarFormatter(action, this._getDefaultMetavarForPositional(action))(1);
      return metavar;
    }
    const parts = [];
    if (action.nargs === 0) {
      parts.push(...action.optionStrings);
    } else {
      const argsString = this._formatArgs(action, this._getDefaultMetavarForOptional(action));
      for (const optionString of action.optionStrings) {
        parts.push(`${optionString} ${argsString}`);
      }
    }
    return parts.join(', ');
  }

  _metavarFormatter(action, defaultMetavar) {
    let result;
    if (action.metavar !== null && action.metavar !== undefined) result = action.metavar;
    else if (action.choices !== null && action.choices !== undefined) {
      result = '{' + action.choices.join(',') + '}';
    } else result = defaultMetavar;
    return (size) => (Array.isArray(result) ? result : new Array(size).fill(result));
  }

  _formatArgs(action, defaultMetavar) {
    const getMetavar = this._metavarFormatter(action, defaultMetavar);
    if (action.nargs === null || action.nargs === undefined) return `${getMetavar(1)[0]}`;
    if (action.nargs === OPTIONAL) return `[${getMetavar(1)[0]}]`;
    const metavars = getMetavar(action.nargs);
    return metavars.join(' ');
  }

  _expandHelp(action) {
    return action.help; // no %(default)s-style substitutions in this program
  }

  _splitLines(text, width) {
    return wrapText(normalizeWhitespace(text), width);
  }

  _getDefaultMetavarForOptional(action) {
    return action.dest.toUpperCase();
  }

  _getDefaultMetavarForPositional(action) {
    return action.dest;
  }
}

export class Action {
  constructor({
    optionStrings = [],
    dest = null,
    nargs = null,
    constValue = null,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
    actionType = 'store',
  } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.const = constValue;
    this.default = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.actionType = actionType;
  }
}

// argparse._get_action_name
function getActionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings.length) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== SUPPRESS) return action.metavar;
  if (action.dest !== null && action.dest !== SUPPRESS) return action.dest;
  return null;
}

export class ArgumentError extends Error {
  constructor(argument, message) {
    super(message);
    this.argumentName = getActionName(argument);
    this.pyMessage = message;
  }

  toString() {
    if (this.argumentName === null) return this.pyMessage;
    return `argument ${this.argumentName}: ${this.pyMessage}`;
  }
}

// Stands in for SystemExit: carries the structured result back to parseArgs.
class ArgparseExit extends Error {
  constructor(result) {
    super('argparse exit');
    this.result = result;
  }
}

// shutil.get_terminal_size(): COLUMNS if it is a valid int, else the (80, 24)
// fallback when stdout is not a tty.
function terminalColumns(columns) {
  if (columns === null || columns === undefined) return 80;
  if (typeof columns === 'number') {
    return Number.isInteger(columns) && columns > 0 ? columns : 80;
  }
  const text = String(columns).trim();
  if (!text) return 80;
  let i = 0;
  let sign = 1;
  if (text[0] === '+' || text[0] === '-') {
    if (text[0] === '-') sign = -1;
    i = 1;
  }
  if (i >= text.length) return 80;
  let value = 0;
  for (; i < text.length; i += 1) {
    if (!ASCII_DIGITS.includes(text[i])) return 80;
    value = value * 10 + ASCII_DIGITS.indexOf(text[i]);
  }
  value *= sign;
  return value > 0 ? value : 80;
}

export class ArgumentParser {
  constructor(options = {}) {
    const {
      // The reference binary is a PyInstaller bundle, so Python's default
      // `os.path.basename(sys.argv[0])` resolves to 'test4_executable'.
      prog = 'test4_executable',
      usage = null,
      description = null,
      epilog = null,
      prefixChars = '-',
      addHelp = true,
      allowAbbrev = true,
      columns = null,
    } = options;

    this.prog = prog;
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;
    this.width = terminalColumns(columns) - 2;

    this._actions = [];
    this._optionStringActions = new Map();
    this._positionalsGroup = { title: 'positional arguments', description: null, actions: [] };
    this._optionalsGroup = { title: 'options', description: null, actions: [] };
    this._actionGroups = [this._positionalsGroup, this._optionalsGroup];
    this._hasNegativeNumberOptionals = false;

    if (addHelp) {
      const prefix = prefixChars.includes('-') ? '-' : prefixChars[0];
      this.addArgument(prefix + 'h', prefix + prefix + 'help', {
        actionType: 'help',
        defaultValue: SUPPRESS,
        help: 'show this help message and exit',
      });
    }
  }

  // add_argument(*option_strings, **kwargs)
  addArgument(...args) {
    let kwargs = {};
    if (args.length && typeof args[args.length - 1] === 'object' && args[args.length - 1] !== null) {
      kwargs = args.pop();
    }
    const optionStrings = args.slice();
    if (!optionStrings.length) {
      throw new Error('this argparse replica only supports optional arguments');
    }

    const longOptionStrings = optionStrings.filter(
      (s) => s.length > 1 && this.prefixChars.includes(s[1]),
    );
    let dest = kwargs.dest !== undefined && kwargs.dest !== null ? kwargs.dest : null;
    if (dest === null) {
      const destOptionString = longOptionStrings.length ? longOptionStrings[0] : optionStrings[0];
      let stripped = destOptionString;
      while (stripped.length && this.prefixChars.includes(stripped[0])) stripped = stripped.slice(1);
      if (!stripped) throw new Error(`dest= is required for options like ${pyRepr(destOptionString)}`);
      dest = stripped.replaceAll('-', '_');
    }

    const actionType = kwargs.actionType || 'store';
    const action = new Action({
      optionStrings,
      dest,
      nargs: actionType === 'store' ? (kwargs.nargs !== undefined ? kwargs.nargs : null) : 0,
      defaultValue: kwargs.defaultValue !== undefined ? kwargs.defaultValue : null,
      type: kwargs.type !== undefined ? kwargs.type : null,
      choices: kwargs.choices !== undefined ? kwargs.choices : null,
      required: kwargs.required === true,
      help: kwargs.help !== undefined ? kwargs.help : null,
      metavar: kwargs.metavar !== undefined ? kwargs.metavar : null,
      actionType,
    });

    this._actions.push(action);
    this._optionalsGroup.actions.push(action);
    for (const optionString of optionStrings) {
      this._optionStringActions.set(optionString, action);
      if (isNegativeNumber(optionString)) this._hasNegativeNumberOptionals = true;
    }
    return action;
  }

  _getFormatter() {
    return new HelpFormatter(this.prog, 2, 24, this.width);
  }

  formatUsage() {
    const formatter = this._getFormatter();
    formatter.addUsage(this.usage, this._actions);
    return formatter.formatHelp();
  }

  formatHelp() {
    const formatter = this._getFormatter();
    formatter.addUsage(this.usage, this._actions);
    formatter.addText(this.description);
    for (const group of this._actionGroups) {
      formatter.startSection(group.title);
      formatter.addText(group.description);
      formatter.addArguments(group.actions);
      formatter.endSection();
    }
    formatter.addText(this.epilog);
    return formatter.formatHelp();
  }

  _errorResult(message) {
    return {
      ok: false,
      exitCode: 2,
      stdout: '',
      stderr: this.formatUsage() + `${this.prog}: error: ${message}\n`,
    };
  }

  _error(message) {
    throw new ArgparseExit(this._errorResult(message));
  }

  parseArgs(argv) {
    const result = this.parseKnownArgs(argv);
    if (!result.ok) return result;
    if (result.extras.length) {
      return this._errorResult(`unrecognized arguments: ${result.extras.join(' ')}`);
    }
    return { ok: true, args: result.args };
  }

  parseKnownArgs(argv) {
    const args = argv === null || argv === undefined ? [] : argv.slice();
    const namespace = {};
    for (const action of this._actions) {
      if (action.dest !== SUPPRESS && action.default !== SUPPRESS) {
        namespace[action.dest] = action.default;
      }
    }
    try {
      const [ns, extras] = this._parseKnownArgs(args, namespace);
      return { ok: true, args: ns, extras };
    } catch (e) {
      if (e instanceof ArgparseExit) return e.result;
      if (e instanceof ArgumentError) return this._errorResult(String(e));
      throw e;
    }
  }

  _parseKnownArgs(argStrings, namespace) {
    // find all option indices, and determine the arg_string_pattern, which has
    // an 'O' where there is an option, an 'A' where there is an argument and a
    // '-' for a '--' separator.
    const optionStringIndices = new Map();
    const patternParts = [];
    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (argString === '--') {
        patternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
        break; // CPython drains the iterator, ending the outer loop too
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        patternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        patternParts.push('O');
      }
    }
    const argStringsPattern = patternParts.join('');

    const seenActions = new Set();
    const seenNonDefaultActions = new Set();
    const extras = [];

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this._getValues(action, argumentStrings);
      if (argumentValues !== action.default) seenNonDefaultActions.add(action);
      if (argumentValues !== SUPPRESS) {
        this._callAction(action, namespace, argumentValues, optionString);
      }
    };

    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
      const actionTuples = [];
      let stop = startIndex + 1;
      for (;;) {
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');
          const chars = this.prefixChars;
          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
            // `-ha` splits into `-h` + `-a`; `-h=x` and `-h-x` do not.
            if (sep || chars.includes(explicitArg[0])) {
              throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
            }
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this._optionStringActions.has(optionString)) {
              action = this._optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (!explicitArg) {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
        } else {
          const start = startIndex + 1;
          const selectedPatterns = argStringsPattern.slice(start);
          const argCount = this._matchArgument(action, selectedPatterns);
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }
      for (const [a, argsForAction, optString] of actionTuples) {
        takeAction(a, argsForAction, optString);
      }
      return stop;
    };

    // This parser defines no positionals, so `_match_arguments_partial` always
    // returns an empty list and consume_positionals is the identity.
    const consumePositionals = (startIndex) => startIndex;

    let startIndex = 0;
    let maxOptionStringIndex = -1;
    for (const index of optionStringIndices.keys()) {
      if (index > maxOptionStringIndex) maxOptionStringIndex = index;
    }
    while (startIndex <= maxOptionStringIndex) {
      let nextOptionStringIndex = Infinity;
      for (const index of optionStringIndices.keys()) {
        if (index >= startIndex && index < nextOptionStringIndex) nextOptionStringIndex = index;
      }
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
      }
      if (startIndex !== nextOptionStringIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }
      startIndex = consumeOptional(startIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    const requiredActions = [];
    for (const action of this._actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(getActionName(action));
      }
    }
    if (requiredActions.length) {
      this._error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }

  // Returns [action, optionString, sep, explicitArg] or null for a positional.
  _parseOptional(argString) {
    if (!argString) return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this._optionStringActions.has(optionString)) {
        return [this._optionStringActions.get(optionString), optionString, '=', explicitArg];
      }
    }

    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
      this._error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    if (isNegativeNumber(argString)) {
      if (!this._hasNegativeNumberOptionals) return null;
    }
    if (argString.includes(' ')) return null;

    return [null, argString, null, null];
  }

  _getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;
    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      if (this.allowAbbrev) {
        const eq = optionString.indexOf('=');
        let optionPrefix;
        let sep;
        let explicitArg;
        if (eq !== -1) {
          optionPrefix = optionString.slice(0, eq);
          sep = '=';
          explicitArg = optionString.slice(eq + 1);
        } else {
          optionPrefix = optionString;
          sep = null;
          explicitArg = null;
        }
        for (const [known, action] of this._optionStringActions) {
          if (known.startsWith(optionPrefix)) result.push([action, known, sep, explicitArg]);
        }
      }
    } else if (chars.includes(optionString[0]) && !chars.includes(optionString[1])) {
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [known, action] of this._optionStringActions) {
        if (known === shortOptionPrefix) {
          result.push([action, known, '', shortExplicitArg]);
        } else if (this.allowAbbrev && known.startsWith(optionPrefix)) {
          result.push([action, known, null, null]);
        }
      }
    } else {
      this._error(`unrecognized option: ${optionString}`);
    }
    return result;
  }

  // `_get_nargs_pattern` for an optional strips every '-'/'-*', so nargs=None
  // becomes '(A)' and nargs=0 becomes '()'. Those are the only two this
  // program uses, so the pattern match reduces to a prefix test.
  _matchArgument(action, argStringsPattern) {
    const nargs = action.nargs;
    if (nargs === 0) return 0;
    if (nargs === null || nargs === undefined) {
      if (argStringsPattern.startsWith('A')) return 1;
      throw new ArgumentError(action, 'expected one argument');
    }
    if (nargs === OPTIONAL) {
      return argStringsPattern.startsWith('A') ? 1 : 0;
    }
    throw new ArgumentError(action, `expected ${nargs} argument${nargs === 1 ? '' : 's'}`);
  }

  _getValues(action, argStrings) {
    // Python 3.12 only strips a '--' for positionals, so nothing to do here.
    if (argStrings.length === 1 && (action.nargs === null || action.nargs === undefined || action.nargs === OPTIONAL)) {
      return this._getValue(action, argStrings[0]);
    }
    return argStrings.map((v) => this._getValue(action, v));
  }

  _getValue(action, argString) {
    // The only `type` this program uses is `str`, which is the identity here.
    return action.type === null || action.type === undefined ? argString : action.type(argString);
  }

  _callAction(action, namespace, values, optionString) {
    if (action.actionType === 'help') {
      throw new ArgparseExit({ ok: false, exitCode: 0, stdout: this.formatHelp(), stderr: '' });
    }
    if (action.actionType === 'store_true') {
      namespace[action.dest] = true;
      return;
    }
    namespace[action.dest] = values;
  }
}

// ---------------------------------------------------------------------------
// Python traceback rendering for a YAMLError that escapes the script.
// ---------------------------------------------------------------------------

const F = (file, line, name) => ({ file, line, name });

const SAFE_LOAD = [F('yaml/__init__.py', 125, 'safe_load'), F('yaml/__init__.py', 81, 'load')];

// Frame chains observed from the reference binary. The real chain depends on
// which parser/scanner method raised, so these are the representative path for
// each exception type; a caller (or the error itself, via `.pyTraceback`) can
// supply the exact frames instead.
const DEFAULT_FRAMES = new Map([
  ['yaml.reader.ReaderError', [
    F('yaml/__init__.py', 125, 'safe_load'), F('yaml/__init__.py', 79, 'load'),
    F('yaml/loader.py', 34, '__init__'), F('yaml/reader.py', 74, '__init__'),
    F('yaml/reader.py', 143, 'check_printable'),
  ]],
  ['yaml.scanner.ScannerError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 49, 'get_single_data'),
    F('yaml/composer.py', 35, 'get_single_node'),
    F('yaml/parser.py', 98, 'check_event'),
    F('yaml/parser.py', 142, 'parse_implicit_document_start'),
    F('yaml/scanner.py', 116, 'check_token'),
    F('yaml/scanner.py', 258, 'fetch_more_tokens'),
  ]],
  ['yaml.parser.ParserError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 49, 'get_single_data'),
    F('yaml/composer.py', 35, 'get_single_node'),
    F('yaml/parser.py', 98, 'check_event'),
    F('yaml/parser.py', 157, 'parse_implicit_document_start'),
    F('yaml/parser.py', 171, 'parse_document_start'),
  ]],
  ['yaml.composer.ComposerError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 49, 'get_single_data'),
    F('yaml/composer.py', 36, 'get_single_node'),
    F('yaml/composer.py', 55, 'compose_document'),
    F('yaml/composer.py', 68, 'compose_node'),
  ]],
  ['yaml.constructor.ConstructorError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 51, 'get_single_data'),
    F('yaml/constructor.py', 55, 'construct_document'),
    F('yaml/constructor.py', 100, 'construct_object'),
    F('yaml/constructor.py', 427, 'construct_undefined'),
  ]],
  ['ValueError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 51, 'get_single_data'),
    F('yaml/constructor.py', 55, 'construct_document'),
    F('yaml/constructor.py', 100, 'construct_object'),
    F('yaml/constructor.py', 263, 'construct_yaml_int'),
  ]],
  ['TypeError', [
    ...SAFE_LOAD,
    F('yaml/constructor.py', 51, 'get_single_data'),
    F('yaml/constructor.py', 55, 'construct_document'),
    F('yaml/constructor.py', 100, 'construct_object'),
  ]],
]);

export function defaultTracebackFrames(err) {
  const name = err && err.qualifiedName ? err.qualifiedName : '';
  return DEFAULT_FRAMES.get(name) || SAFE_LOAD;
}

// Renders exactly what CPython writes to stderr for an uncaught exception:
//
//   Traceback (most recent call last):
//     File "test4.py", line 8, in <module>
//     ...
//   yaml.parser.ParserError: <message>
//
// When `pid` is given, the PyInstaller trailer the reference bundle prints is
// appended too (its number is the process id).
export function formatTraceback(err, options = {}) {
  const {
    scriptFile = 'test4.py',
    scriptLine = 8,
    scriptFunc = '<module>',
    frames = null,
    pid = null,
    pyiScript = 'test4',
  } = options;

  const chain = frames || (err && err.pyTraceback) || defaultTracebackFrames(err);
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${scriptFile}", line ${scriptLine}, in ${scriptFunc}\n`;
  for (const frame of chain) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  const name = (err && err.qualifiedName) || (err && err.constructor && err.constructor.name) || 'Exception';
  const message = err && err.message !== undefined && err.message !== null ? String(err.message) : '';
  out += message === '' ? `${name}\n` : `${name}: ${message}\n`;
  if (pid !== null && pid !== undefined) {
    out += `[PYI-${pid}:ERROR] Failed to execute script '${pyiScript}' due to unhandled exception!\n`;
  }
  return out;
}
